/**
 * Creates the monthly, customer level, billing schedule for a customer
 */
private async createBillingSchedule({
    customerId,
    businessID,
    subject,
}: {
    customerId: string;
    businessID: string;
    subject: string;
}) {
    CustomerService.logger.log(`Creating billing schedule for customer: ${customerId} of business: ${businessID}`);
    return this.schedulerService.create({
        schedulerID: customerId,
        schedulerType: schedulerType.billing,
        schedulerStatus: SchedulerStatus.live,
        scheduleParameters: { customerId, businessID },
        rate: SupportedMeasurementFrequencies.monthly,
        subject,
        businessID,
    });
}

/**
 * Swaps the billing schedule of a customer for a new customer level one.
 * A missing schedule is not an error, the customer may never have had an offering attached to it.
 */
private async replaceBillingSchedule({
    customerId,
    businessID,
    subject,
}: {
    customerId: string;
    businessID: string;
    subject: string;
}) {
    try {
        await this.schedulerService.remove({ schedulerID: customerId, businessID, isBillingQueue: true });
    } catch (e) {
        if (e instanceof NotFoundException) {
            CustomerService.logger.log(`No billing schedule found for customer ${customerId} to replace`);
        } else {
            throw e;
        }
    }
    await this.createBillingSchedule({ customerId, businessID, subject });
}

