import { Billing, billingScheduleConsumers } from '../billing/entities/billing.entity';
import { AuditService } from '../audit/audit.service';
import { getQueueToken } from '@nestjs/bull';
import { schedulerType, SchedulerStatus, SupportedMeasurementFrequencies } from '../scheduler/dto/scheduler.dto';
import { MeasurementConfigService } from '../measurement-config/measurement-config.service';
import { DimensionsService } from '../dimensions/dimensions.service';

const point = { tag: jest.fn(), stringField: jest.fn() };

describe('scratch migration checks', () => {
    describe('customer scheduling', () => {
        let service: CustomerService;
        const schedulerService = { create: jest.fn(), remove: jest.fn() };
        const influx = { loadPoints: jest.fn(), getPoint: () => point, getLatestCustomer: jest.fn() };
        beforeEach(async () => {
            jest.resetAllMocks();
            const module: TestingModule = await Test.createTestingModule({
                providers: [
                    CustomerService,
                    { provide: InfluxService, useValue: influx },
                    { provide: SchedulerService, useValue: schedulerService },
                    { provide: ServicesService, useValue: {} },
                    { provide: OfferingService, useValue: {} },
                    { provide: UsageService, useValue: {} },
                ],
            }).compile();
            service = module.get(CustomerService);
        });

        it('does not schedule billing without an offering', async () => {
            await service.create({ customerName: 'a', businessID: 'biz' } as never, 'auth|1');
            expect(schedulerService.create).not.toHaveBeenCalled();
        });

        it('schedules monthly billing with an offering', async () => {
            await service.create({ customerName: 'a', businessID: 'biz', offeringId: 'off' } as never, 'auth|1');
            expect(schedulerService.create).toHaveBeenCalledWith(
                expect.objectContaining({
                    schedulerType: schedulerType.billing,
                    schedulerStatus: SchedulerStatus.live,
                    rate: SupportedMeasurementFrequencies.monthly,
                    subject: 'auth|1',
                    businessID: 'biz',
                })
            );
        });

        it('replaces the schedule when an offering changes, tolerating a missing one', async () => {
            jest.spyOn(service, 'findOne').mockResolvedValue({
                data: [{ customerId: 'cust', offeringId: 'old' } as never],
                message: '',
            });
            schedulerService.remove.mockRejectedValue(new NotFoundException('nope'));
            await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'new' }, 'auth|1');
            expect(schedulerService.remove).toHaveBeenCalledWith({
                schedulerID: 'cust',
                businessID: 'biz',
                isBillingQueue: true,
            });
            expect(schedulerService.create).toHaveBeenCalledWith(
                expect.objectContaining({
                    schedulerID: 'cust',
                    subject: 'auth|1',
                    businessID: 'biz',
                    scheduleParameters: { customerId: 'cust', businessID: 'biz' },
                })
            );
        });

        it('leaves the schedule alone when the offering is unchanged', async () => {
            jest.spyOn(service, 'findOne').mockResolvedValue({
                data: [{ customerId: 'cust', offeringId: 'old' } as never],
                message: '',
            });
            await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'old' }, 'auth|1');
            expect(schedulerService.create).not.toHaveBeenCalled();
            expect(schedulerService.remove).not.toHaveBeenCalled();
        });
    });

    describe('billing job', () => {
        let service: BillingService;
        const customerService = { findOne: jest.fn() };
        const invoicesService = { generateInvoiceForUsageTotal: jest.fn() };
        const influx = { loadPoints: jest.fn(), getPoint: () => point };
        beforeEach(async () => {
            jest.resetAllMocks();
            const module: TestingModule = await Test.createTestingModule({
                providers: [
                    BillingService,
                    { provide: InfluxService, useValue: influx },
                    { provide: CustomerService, useValue: customerService },
                    { provide: InvoicesService, useValue: invoicesService },
                ],
            }).compile();
            service = module.get(BillingService);
        });

        it('bills the customer for the offering billing cycle', async () => {
            customerService.findOne.mockResolvedValue({
                data: [{ customerId: 'cust', offeringId: 'off', offering: { billingCycle: 'monthly' } }],
            });
            invoicesService.generateInvoiceForUsageTotal.mockResolvedValue({ invoiceId: 'inv-1' });
            const { startTime, endTime } = Billing.billingCycleToTimeRange('monthly' as never);
            await service.create({
                data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } },
            } as never);
            expect(customerService.findOne).toHaveBeenCalledWith({ customerId: 'cust', businessID: 'biz' });
            expect(invoicesService.generateInvoiceForUsageTotal).toHaveBeenCalledWith({
                businessID: 'biz',
                customerId: 'cust',
                start: startTime,
                end: endTime,
            });
            expect(influx.loadPoints).toHaveBeenCalled();
            expect(point.tag).toHaveBeenCalledWith('invoiceId', 'inv-1');
        });

        it('does nothing when the customer has no offering', async () => {
            customerService.findOne.mockResolvedValue({ data: [{ customerId: 'cust' }] });
            await service.create({
                data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } },
            } as never);
            expect(invoicesService.generateInvoiceForUsageTotal).not.toHaveBeenCalled();
            expect(influx.loadPoints).not.toHaveBeenCalled();
        });

        it('audits failures instead of storing a partial record', async () => {
            const auditSpy = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
            customerService.findOne.mockResolvedValue({
                data: [{ customerId: 'cust', offering: { billingCycle: 'monthly' } }],
            });
            invoicesService.generateInvoiceForUsageTotal.mockRejectedValue(new Error('boom'));
            await service.create({
                data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } },
            } as never);
            expect(auditSpy).toHaveBeenCalled();
            expect(influx.loadPoints).not.toHaveBeenCalled();
        });
    });

    describe('scheduler emissions', () => {
        let service: SchedulerService;
        const queue = { add: jest.fn() };
        const billingQueue = { add: jest.fn() };
        beforeEach(async () => {
            jest.resetAllMocks();
            const module: TestingModule = await Test.createTestingModule({
                providers: [
                    SchedulerService,
                    { provide: getQueueToken('scheduler_queue'), useValue: queue },
                    { provide: getQueueToken('scheduler_billing_queue'), useValue: billingQueue },
                ],
            }).compile();
            service = module.get(SchedulerService);
        });

        it('emits billing on the billing queue', async () => {
            await service.emitOne({
                schedulerId: 'sched',
                payload: {
                    schedulerType: schedulerType.billing,
                    businessID: 'biz',
                    scheduleParameters: { customerId: 'cust', businessID: 'biz' },
                },
            });
            expect(billingQueue.add).toHaveBeenCalledWith(
                billingScheduleConsumers.billingReport,
                expect.objectContaining({ businessID: 'biz', schedulerID: 'sched' })
            );
            expect(queue.add).not.toHaveBeenCalled();
        });

        it('emits measurements on the scheduler queue', async () => {
            await service.emitOne({
                schedulerId: 'sched',
                payload: {
                    schedulerType: schedulerType.dimensionDataGathering,
                    dimensionType: 'ebsVolume',
                    businessID: 'biz',
                    scheduleParameters: {},
                },
            });
            expect(queue.add).toHaveBeenCalledWith('ebsVolume', expect.objectContaining({ businessID: 'biz' }));
            expect(billingQueue.add).not.toHaveBeenCalled();
        });
    });

    describe('usage reads', () => {
        it('returns an empty result for a customer without an offering', async () => {
            const module: TestingModule = await Test.createTestingModule({
                providers: [
                    UsageService,
                    { provide: InfluxService, useValue: {} },
                    { provide: MeasurementConfigService, useValue: {} },
                    { provide: DimensionsService, useValue: {} },
                    { provide: CustomerService, useValue: { findOne: async () => ({ data: [{}] }) } },
                    { provide: OfferingService, useValue: {} },
                ],
            }).compile();
            const service = module.get(UsageService);
            await expect(service.findUsageForCustomer({ customerId: 'c', businessID: 'b' }, {})).resolves.toEqual([]);
        });
    });
});

