                CustomerService,
                { provide: InfluxService, useValue: { loadPoints: jest.fn(), getPoint: () => point } },
                { provide: SchedulerService, useValue: schedulerService },
                { provide: ServicesService, useValue: {} },
                { provide: OfferingService, useValue: {} },
                { provide: UsageService, useValue: {} },
            ],
        }).compile();
        const service = module.get(CustomerService);
        jest.spyOn(service, 'findOne').mockResolvedValue({ data: [{ customerId: 'cust' } as never], message: '' });
        await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'new' }, 'auth|1');
        expect(schedulerService.create).toHaveBeenCalledWith(
            expect.objectContaining({ subject: 'auth|1', businessID: 'biz', schedulerID: 'cust' })
        );
        // subject on the payload works too
        schedulerService.create.mockClear();
        await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'new', subject: 'auth|2' });
        expect(schedulerService.create).toHaveBeenCalledWith(expect.objectContaining({ subject: 'auth|2' }));
    });

    it('billing job uses scheduler businessID and customer offering', async () => {
        const influx = { loadPoints: jest.fn(), getPoint: () => point };
        const customerService = {
            findOne: jest.fn().mockResolvedValue({ data: [{ offering: { billingCycle: 'monthly' } }] }),
        };
        const invoicesService = {
            generateInvoiceForUsageTotal: jest.fn().mockResolvedValue({ invoiceId: 'inv-1' }),
        };
        const module: TestingModule = await Test.createTestingModule({
            providers: [
                BillingService,
                { provide: InfluxService, useValue: influx },
                { provide: CustomerService, useValue: customerService },
                { provide: InvoicesService, useValue: invoicesService },
            ],
        }).compile();
        const service = module.get(BillingService);
        const { startTime, endTime } = Billing.billingCycleToTimeRange('monthly' as never);
        await service.create({
            data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } },
        } as never);
        expect(customerService.findOne).toHaveBeenCalledWith({ customerId: 'cust', businessID: 'biz' });
        expect(invoicesService.generateInvoiceForUsageTotal).toHaveBeenCalledWith({
            businessID: 'biz',
            customerId: 'cust',
            start: startTime,
            end: endTime,
        });
        expect(point.tag).toHaveBeenCalledWith('invoiceId', 'inv-1');
        expect(influx.loadPoints).toHaveBeenCalled();
    });
});
